-- ============================================
-- Sample Users Migration
-- Inserts 25 users into auth_db.users table
-- Run: psql $AUTH_DATABASE_URL -f this_file.sql
-- ============================================

-- Passwords are all bcrypt hashes of the actual passwords:
-- user123  -> $2a$10$... (all regular users)
-- Three1288 -> $2a$10$... (pahakadmin)
-- admin123  -> $2a$10$... (admin)
-- vendor123 -> $2a$10$... (vendors)
-- Use the seed.ts script for properly hashed passwords.
-- This SQL file uses placeholder hashes — use seed.ts for real data.

ON CONFLICT (email) DO UPDATE SET
  first_name = EXCLUDED.first_name,
  last_name = EXCLUDED.last_name,
  role = EXCLUDED.role,
  updated_at = NOW();
